type State = {
  headerIdx: number;   /* logo in the canvas header */
  dropIdx: number;     /* logo in the upload box */
  colorIdx: number;    /* gradient + swatch colour */
  hex: string;         /* text in the hex field */
  typing: boolean;     /* caret visible */
  selecting: boolean;  /* hex text is selected */
  hovering: boolean;   /* pointer is over the upload box */
  pressed: boolean;    /* mouse down */
  cursor: Point;
};

const INITIAL: State = {
  headerIdx: 0,
  dropIdx: 0,
  colorIdx: 0,
  hex: BRANDS[0].hex,
  typing: false,
  selecting: false,
  hovering: false,
  pressed: false,
  cursor: REST_PT,
};

type Step = [number, Partial<State>];

/** One queue of [delay, patch] steps — the whole timeline, in order. */
function buildTimeline(): Step[] {
  const steps: Step[] = [[900, {}]];

  BRANDS.forEach((_, i) => {
    const toIdx = (i + 1) % BRANDS.length; /* the last cycle returns to brand 0 */
    const to = BRANDS[toIdx];
    const chars = to.hex.slice(1).split('');

    /* 1 — pointer snaps into the upload box and clicks */
    steps.push([300, { cursor: DROP_PT, hovering: true, typing: false, selecting: false }]);
    steps.push([360, { pressed: true }]);
    steps.push([90, { pressed: false }]);

    /* 2 — a beat later the new logotype appears; the pointer stays put */
    steps.push([300, { dropIdx: toIdx }]);

    /* 3 — the canvas header picks it up */
    steps.push([760, { headerIdx: toIdx }]);

    /* 4 — pointer moves to the hex field, selects, clears */
    steps.push([820, { cursor: FIELD_PT, hovering: false, pressed: true }]);
    steps.push([90, { pressed: false, typing: true }]);
    steps.push([120, { selecting: true }]);
    steps.push([200, { selecting: false, hex: '#', cursor: REST_PT }]);

    /* 5 — types the new hex, character by character */
    chars.forEach((_c, n) => {
      steps.push([120, { hex: '#' + chars.slice(0, n + 1).join('') }]);
    });

    /* 6 — the canvas recolours on the last character, then holds */
    steps.push([60, { colorIdx: toIdx }]);
    steps.push([1100, { typing: false }]);
  });

  return steps;
}

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener('change', sync);
    return () => mq.removeEventListener('change', sync);
  }, []);
  return reduced;
}

/* ---------------------------------------------------------- components */

function Logotype({ brand, width, height }: { brand: Brand; width: number; height: number }) {
  return (
    <svg viewBox={brand.viewBox} width={width} height={height} aria-hidden="true" focusable="false">
      {brand.paths.map((p, i) => (
        <path key={i} d={p.d} fill={p.fill} opacity={p.opacity} />
      ))}
    </svg>
  );
}

function Pointer({ at, pressed, reduced }: { at: Point; pressed: boolean; reduced: boolean }) {
  return (
    <div
      className={styles.pointer}
      style={{
        transform: `translate(${at.x}px, ${at.y}px) scale(${pressed ? 0.88 : 1})`,
        transition: reduced ? 'none' : 'transform 340ms var(--isc-snap-hard)',
      }}
    >
      <svg width="24" height="24" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
        <path
          d="M2 1.5 L2 18.2 L6.3 14.1 L9.1 20.6 L11.9 19.4 L9.1 13 L15 12.8 Z"
          fill="#FFFFFF"
          stroke="#101829"
          strokeWidth="1.6"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
}

export function CustomiseCanvas({ paused = false }: { paused?: boolean }) {
  const [s, setS] = useState<State>(INITIAL);
  const reduced = usePrefersReducedMotion();
  const timer = useRef<number | undefined>(undefined);
  // A ref, not a dependency of the timeline effect below — toggling it
  // shouldn't tear down and reset the whole state machine, just stop
  // the queue from advancing to its next step until it's false again.
  const pausedRef = useRef(paused);
  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);
  const pumpRef = useRef<() => void>(() => {});

  useEffect(() => {
    const steps = buildTimeline();
    let i = 0;
    let alive = true;

    // Guarded so it's safe to call redundantly: does nothing if a step
    // is already pending (timer.current) or the queue is paused, so the
    // separate "resume" effect below can just call it again once
    // unpaused without risking two steps firing in parallel.
    const pump = () => {
      if (!alive || timer.current || pausedRef.current) return;
      const [delay, patch] = steps[i % steps.length];
      timer.current = window.setTimeout(() => {
        timer.current = undefined;
        if (!alive) return;
        setS((prev) => ({ ...prev, ...patch }));
        i += 1;
        pump();
      }, delay);
    };
    pumpRef.current = pump;

    pump();
    return () => {
      alive = false;
      if (timer.current) window.clearTimeout(timer.current);
    };
  }, []);

  // Resumes the queue right where it stopped once unpaused — pump()
  // itself is a no-op if a step is already scheduled, so this can't
  // double up with the timeline effect's own kickoff above.
  useEffect(() => {
    if (!paused) pumpRef.current();
  }, [paused]);

  return (
    <div className={styles.canvas} style={{ width: CANVAS_W, height: CANVAS_H }}>
      <div className={styles.washBase} />

      {/* the canvas gradient — one layer per brand, cross-faded */}
      {BRANDS.map((b, i) => (
        <div
          key={b.id}
          className={styles.wash}
          style={{
            opacity: i === s.colorIdx ? 1 : 0,
            background:
              `radial-gradient(146.78% 175.82% at 71.77% 132.61%, ` +
              `${hexToRgba(b.hex, 0.8)} 0%, ${hexToRgba(b.hex, 0.1)} 78.37%)`,
          }}
        />
      ))}

      <div className={styles.chrome}>
        <div className={styles.header}>
          <div className={styles.logoSlot}>
            {BRANDS.map((b, i) => (
              <div
                key={b.id}
                className={styles.logoLayer}
                style={{ opacity: i === s.headerIdx ? 1 : 0 }}
              >
                <Logotype brand={b} width={b.headerWidth} height={b.headerHeight} />
              </div>
            ))}
          </div>
          <div className={styles.windowDots}>
            <span />
            <span />
            <span />
          </div>
        </div>

        <div className={styles.body}>
          <div className={styles.column}>
            <div className={styles.paneTop} />
            <div className={styles.paneMain} />
          </div>
          <div className={styles.paneSide} />
        </div>
      </div>

      {/* Customise panel */}
      <div className={styles.modal}>
        <div className={styles.group}>
          <div className={styles.label}>Logotype</div>
          <div className={`${styles.dropzone} ${s.hovering ? styles.dropzoneHover : ''}`}>
            {BRANDS.map((b, i) => (
              <div
                key={b.id}
                className={styles.logoLayer}
                style={{ opacity: i === s.dropIdx ? 1 : 0 }}
              >
                <Logotype brand={b} width={b.dropWidth} height={b.dropHeight} />
              </div>
            ))}
          </div>
        </div>

        <div className={styles.group}>
          <div className={styles.label}>Färg</div>
          <div className={styles.colorRow}>
            <div className={styles.swatch}>
              {BRANDS.map((b, i) => (
                <span
                  key={b.id}
                  className={styles.swatchLayer}
                  style={{ background: b.hex, opacity: i === s.colorIdx ? 1 : 0 }}
                />
              ))}
            </div>
            <div className={`${styles.hexField} ${s.typing ? styles.hexFieldActive : ''}`}>
              <span className={s.selecting ? styles.hexSelected : undefined}>{s.hex}</span>
              <span className={`${styles.caret} ${s.typing ? styles.caretOn : ''}`} />
            </div>
          </div>
        </div>
      </div>

      <Pointer at={s.cursor} pressed={s.pressed} reduced={reduced} />
    </div>
  );
}

/* ------------------------------------------------------------- helpers */

function hexToRgba(hex: string, alpha: number): string {
  const n = hex.replace('#', '');
  const r = parseInt(n.slice(0, 2), 16);
  const g = parseInt(n.slice(2, 4), 16);
  const b = parseInt(n.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
